WITH "per_rows" AS (SELECT "t1"."branch_id" AS "branch_id", MAX("t1"."branch_name") AS "branch_id_label", COUNT(CASE WHEN "t0"."order_date" >= TIMESTAMP '2026-07-31 17:00:00' AND "t0"."order_date" < TIMESTAMP '2026-08-31 17:00:00' THEN 1 END) AS "orders" FROM "sales"."orders" AS "t0" LEFT JOIN "sales"."branches" AS "t1" ON "t0"."branch_id" = "t1"."branch_id" WHERE ("t0"."status" = 'DONE') AND ("t1"."branch_id" IS NOT NULL) AND ("t0"."order_date" >= TIMESTAMP '2026-07-31 17:00:00' AND "t0"."order_date" < TIMESTAMP '2026-08-31 17:00:00') GROUP BY "t1"."branch_id"), "per_keys" AS (SELECT DISTINCT "k"."branch_id" AS "branch_id" FROM "sales"."branches" AS "k" WHERE ("k"."branch_id" IS NOT NULL)), "per" AS (SELECT "per_keys"."branch_id" AS "branch_id", COALESCE("per_rows"."orders", 0) AS "orders" FROM "per_keys" LEFT JOIN "per_rows" ON "per_rows"."branch_id" IS NOT DISTINCT FROM "per_keys"."branch_id") SELECT CASE WHEN "per"."orders" < 1 THEN '0' WHEN "per"."orders" < 100 THEN '1-99' WHEN "per"."orders" >= 100 THEN '100+' END AS "orders_range", COUNT(*) AS "branches" FROM "per" GROUP BY CASE WHEN "per"."orders" < 1 THEN '0' WHEN "per"."orders" < 100 THEN '1-99' WHEN "per"."orders" >= 100 THEN '100+' END ORDER BY MIN("per"."orders") ASC LIMIT 1000
